style.css:
@-moz-document url("https://www.roblox.com/home") {
/* Set full-page Musashi background */
  html, body {
    background: url("https://i.imgur.com/92RiBzI.png") no-repeat center center fixed !important;
    background-size: cover !important;
    height: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
  }

  /* Remove Roblox default backgrounds that cover the page */
  #container, #container-main, .container-main, .content, .navbar, .footer, .main-content,
  .container, .section, .rbx-body {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Add semi-transparent dark overlay behind main content for readability */
  #container, #container-main, .container-main, .content, .navbar, .footer, .main-content {
    background-color: rgba(0, 0, 0, 0.5) !important;
  }

  /* Make all text white for contrast */
  * {
    color: #fff !important;
  }
}
